"""Validate stripe_webhook.py without network access using stubbed stripe/flask."""

import importlib.util
import json
import sys
import types

# --- Stub stripe ---
class SignatureVerificationError(Exception):
    pass

stripe = types.ModuleType("stripe")
stripe.error = types.SimpleNamespace(SignatureVerificationError=SignatureVerificationError)


def fake_construct_event(payload, sig_header, secret):
    if sig_header == "invalid-signature":
        raise SignatureVerificationError("signature does not match")
    if payload != b"valid-payload":
        raise ValueError("request body is not valid json")
    return json.loads(payload)


stripe.Webhook = types.SimpleNamespace(construct_event=fake_construct_event)
sys.modules["stripe"] = stripe

# --- Stub flask ---
class _Flask:
    def __init__(self, import_name):
        self.import_name = import_name
        self.routes = {}

    def route(self, rule, **kwargs):
        def decorator(fn):
            self.routes[rule] = fn
            return fn

        return decorator


class _FakeRequest:
    def __init__(self, payload=b"", headers=None):
        self._payload = payload
        self.headers = headers or {}

    def get_data(self):
        return self._payload


flask = types.ModuleType("flask")
flask.Flask = _Flask
flask.request = _FakeRequest()
sys.modules["flask"] = flask

# --- Load the target module ---
spec = importlib.util.spec_from_file_location("stripe_webhook", "stripe_webhook.py")
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)

passed = 0
failed = 0


def check(name, condition, detail=""):
    global passed, failed
    if condition:
        passed += 1
        print(f"PASS {name}")
    else:
        failed += 1
        print(f"FAIL {name} {detail}")


def call_webhook(payload, headers):
    module.request = _FakeRequest(payload, headers)
    return module.webhook()


# 1. Missing Stripe-Signature header
body, status = call_webhook(b"valid-payload", {})
check("missing signature -> 400", status == 400 and "Stripe-Signature" in body)

# 2. Invalid signature
body, status = call_webhook(b"valid-payload", {"Stripe-Signature": "invalid-signature"})
check("invalid signature -> 400", status == 400 and body == "Invalid signature")

# 3. Invalid payload
body, status = call_webhook(b"not-json", {"Stripe-Signature": "t=1,v1=abc"})
check("invalid payload -> 400", status == 400 and body == "Invalid payload")

# 4. payment_intent.succeeded
succeeded_event = {
    "id": "evt_succeeded_1",
    "type": "payment_intent.succeeded",
    "data": {
        "object": {
            "id": "pi_123",
            "status": "succeeded",
            "customer": "cus_1",
            "amount": 2000,
            "currency": "usd",
            "metadata": {"order_id": "order_1"},
        }
    },
}
body, status = call_webhook(
    json.dumps(succeeded_event).encode(), {"Stripe-Signature": "t=1,v1=abc"}
)
check("succeeded event -> 200", status == 200 and body == "Success")
rec = module.RECORDS[-1] if module.RECORDS else {}
check(
    "succeeded event recorded",
    rec.get("payment_intent_id") == "pi_123" and rec.get("order_id") == "order_1",
)

# 5. Idempotent replay of the same event
records_before = len(module.RECORDS)
body, status = call_webhook(
    json.dumps(succeeded_event).encode(), {"Stripe-Signature": "t=1,v1=abc"}
)
check("replay -> 200", status == 200)
check("replay not processed twice", len(module.RECORDS) == records_before)

# 6. payment_intent.payment_failed
failed_event = {
    "id": "evt_failed_1",
    "type": "payment_intent.payment_failed",
    "data": {
        "object": {
            "id": "pi_456",
            "status": "requires_payment_method",
            "customer": "cus_2",
            "last_payment_error": {
                "decline_code": "card_declined",
                "message": "Your card was declined.",
            },
        }
    },
}
body, status = call_webhook(
    json.dumps(failed_event).encode(), {"Stripe-Signature": "t=1,v1=abc"}
)
check("failed event -> 200", status == 200)
rec = module.RECORDS[-1] if module.RECORDS else {}
check(
    "failure recorded with decline code",
    rec.get("decline_code") == "card_declined",
)

# 7. Unknown event type is acknowledged (not an error)
unknown_event = {"id": "evt_unknown_1", "type": "charge.refunded", "data": {"object": {}}}
body, status = call_webhook(
    json.dumps(unknown_event).encode(), {"Stripe-Signature": "t=1,v1=abc"}
)
check("unknown event type -> 200", status == 200)

# 8. Handler failure -> 500 so Stripe retries
original_handler = module.EVENT_HANDLERS["payment_intent.succeeded"]


def boom(payment_intent):
    raise RuntimeError("database down")


module.EVENT_HANDLERS["payment_intent.succeeded"] = boom
boom_event = {
    "id": "evt_boom_1",
    "type": "payment_intent.succeeded",
    "data": {"object": {"id": "pi_boom"}},
}
body, status = call_webhook(
    json.dumps(boom_event).encode(), {"Stripe-Signature": "t=1,v1=abc"}
)
check("handler failure -> 500 (retry)", status == 500 and body == "Processing failed")
module.EVENT_HANDLERS["payment_intent.succeeded"] = original_handler

# 9. Event without an id -> 500 (refuses to silently mark as processed)
no_id_event = {"type": "payment_intent.succeeded", "data": {"object": {}}}
body, status = call_webhook(
    json.dumps(no_id_event).encode(), {"Stripe-Signature": "t=1,v1=abc"}
)
check("event without id -> 500", status == 500)

print(f"\n{passed} passed, {failed} failed")
sys.exit(1 if failed else 0)

